import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { roundCents } from './money.js';
import { nextInvoiceNumber } from './numbering.js';

/**
 * Create a new invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }> }} input
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: 'draft', lines: Array } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  // Validate customer
  const customerResult = getCustomer(customerId);
  if (!customerResult.ok) return customerResult;
  const customer = customerResult.value;

  // Validate issue date
  const dateError = validateIssueDate(issueDate);
  if (dateError) return fail(dateError);

  // Validate lines array
  if (!Array.isArray(lines) || lines.length === 0) {
    return fail('NO_LINES');
  }

  // Process and validate each line
  const processedLines = [];
  for (const line of lines) {
    // Validate quantity
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    // Determine discount: explicit value wins, otherwise use tier discount
    const discountPercent = line.discountPercent !== undefined && line.discountPercent !== null
      ? line.discountPercent
      : TIER_DISCOUNTS[customer.tier];

    // Validate discount percent
    const discountError = validateDiscountPercent(discountPercent);
    if (discountError) return fail(discountError);

    // Validate SKU and get product
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    processedLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  // Build invoice
  const invoice = {
    customerId,
    issueDate,
    status: 'draft',
    lines: processedLines,
  };

  return ok(invoice);
}

/**
 * Calculate the total for a single invoice line.
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number} total in cents
 */
export function lineTotal(line) {
  return roundCents(line.qty * line.unitPrice);
}

/**
 * Calculate the discount for a single invoice line.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {number} discount in cents
 */
export function lineDiscount(line) {
  const total = lineTotal(line);
  const discount = (total * (line.discountPercent ?? 0)) / 100;
  return roundCents(discount);
}

/**
 * Calculate the VAT for a single invoice line.
 * VAT is computed on the line amount after discount.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }} line
 * @returns {number} VAT in cents
 */
export function lineVAT(line) {
  const subtotal = lineTotal(line);
  const discount = lineDiscount(line);
  const amountAfterDiscount = subtotal - discount;
  const vat = (amountAfterDiscount * line.vatRate) / 100;
  return roundCents(vat);
}

/**
 * Calculate totals for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }> }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, total: number }} amounts in cents
 */
export function invoiceTotals(invoice) {
  let subtotal = 0;
  let discount = 0;
  let vat = 0;
  for (const line of invoice.lines) {
    subtotal += lineTotal(line);
    discount += lineDiscount(line);
    vat += lineVAT(line);
  }
  const total = Math.max(0, subtotal - discount + vat);
  return {
    subtotal,
    discount,
    vat,
    total,
  };
}

/**
 * Add or increase a line on a draft invoice.
 * @param {{ status: string, customerId: string, lines: Array<{ sku: string, qty: number }> }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} input
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  // Check status
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Validate quantity
  if (!Number.isInteger(qty) || qty <= 0) {
    return fail('QTY_INVALID');
  }

  // Get customer for tier discount
  const customerResult = getCustomer(invoice.customerId);
  if (!customerResult.ok) return customerResult;
  const customer = customerResult.value;

  // Determine discount: explicit value wins, otherwise use tier discount
  const finalDiscount = discountPercent !== undefined && discountPercent !== null
    ? discountPercent
    : TIER_DISCOUNTS[customer.tier];

  // Validate discount percent
  const discountError = validateDiscountPercent(finalDiscount);
  if (discountError) return fail(discountError);

  // Validate SKU and get product
  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  // Create new invoice with updated lines
  const newLines = invoice.lines.map((line) => ({ ...line }));
  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);

  if (existingLineIndex >= 0) {
    // Line exists, increase qty
    newLines[existingLineIndex] = {
      ...newLines[existingLineIndex],
      qty: newLines[existingLineIndex].qty + qty,
    };
  } else {
    // New line, add it
    const product = productResult.value;
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: finalDiscount,
    });
  }

  // Return new invoice
  const newInvoice = {
    ...invoice,
    lines: newLines,
  };
  return ok(newInvoice);
}

/**
 * Remove a line from a draft invoice.
 * @param {{ status: string, lines: Array<{ sku: string }> }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  // Check status
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Find the line
  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex < 0) {
    return fail('LINE_NOT_FOUND');
  }

  // Check if this is the last line
  if (invoice.lines.length === 1) {
    return fail('NO_LINES');
  }

  // Create new invoice without this line
  const newLines = invoice.lines.filter((line) => line.sku !== sku);
  const newInvoice = {
    ...invoice,
    lines: newLines,
  };
  return ok(newInvoice);
}

/**
 * Issue a draft invoice.
 * @param {{ status: string, issueDate: string }} invoice
 * @param {Array<string>} existingNumbers array of invoice numbers already used
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  // Check status
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Generate invoice number
  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  // Return new invoice with number and issued status
  const newInvoice = {
    ...invoice,
    number,
    status: 'issued',
  };
  return ok(newInvoice);
}

/**
 * Validate discount percent value.
 * @param {unknown} value
 * @returns {string | null} error code or null if valid
 */
function validateDiscountPercent(value) {
  if (value === undefined || value === null) {
    return null;
  }
  if (typeof value !== 'number' || value < 0 || value > 100) {
    return 'DISCOUNT_INVALID';
  }
  return null;
}

/**
 * Validate issue date format and that it's a real date.
 * @param {string} dateStr
 * @returns {string | null} error code or null if valid
 */
function validateIssueDate(dateStr) {
  if (typeof dateStr !== 'string') return 'DATE_INVALID';

  // Check format YYYY-MM-DD
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(dateStr);
  if (!match) return 'DATE_INVALID';

  const year = parseInt(match[1], 10);
  const month = parseInt(match[2], 10);
  const day = parseInt(match[3], 10);

  // Validate month and day ranges
  if (month < 1 || month > 12 || day < 1 || day > 31) {
    return 'DATE_INVALID';
  }

  // Check if it's a real date by creating a Date and verifying
  const date = new Date(`${dateStr}T00:00:00Z`);
  if (isNaN(date.getTime())) return 'DATE_INVALID';

  // Verify that the date components match (handles invalid dates like Feb 30)
  if (date.getUTCFullYear() !== year || date.getUTCMonth() + 1 !== month || date.getUTCDate() !== day) {
    return 'DATE_INVALID';
  }

  return null;
}

