test('invoiceTotals sums all line totals', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500, vatRate: 0 },
      { qty: 10, unitPrice: 9500, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 42500 + 95000); // 137500
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 137500);
});

test('invoiceTotals with single line', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 120000, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 120000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 120000);
});

test('invoiceTotals with multiple lines of varying amounts', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 1000, vatRate: 0 },
      { qty: 3, unitPrice: 5000, vatRate: 0 },
      { qty: 1, unitPrice: 10000, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // 2*1000 + 3*5000 + 1*10000 = 2000 + 15000 + 10000 = 27000
  assert.equal(totals.subtotal, 27000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 27000);
});

test('invoiceTotals on a created invoice', () => {
  // C-002 is standard tier (0% discount)
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // DES-HOUR: 5 * 8500 = 42500, VAT 21% = 8925
  // DEV-HOUR: 3 * 9500 = 28500, VAT 21% = 5985
  // Total (standard tier, 0% discount, with VAT): 71000 + 14910 = 85910
  assert.equal(totals.subtotal, 71000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 14910);
  assert.equal(totals.total, 85910);
});

